// LockLiveSettlement is a draft write's lock (plan reading 7): the live
// settlement of (supply period, period, kind) as ux_settlements_live counts
// it — a draft, or an invoiced regular one —, FOR NO KEY UPDATE, so a racing
// Settle or the holder's stamp waits.
func (q *Queries) LockLiveSettlement(ctx context.Context, arg LockLiveSettlementParams) (EnergySettlement, error) {
	row := q.db.QueryRow(ctx, lockLiveSettlement, arg.SupplyPeriodID, arg.PeriodStart, arg.Kind)
	var i EnergySettlement
	err := row.Scan(
		&i.ID,
		&i.SupplyPeriodID,
		&i.MeteringPointID,
		&i.CustomerID,
		&i.Kind,
		&i.CorrectsID,
		&i.PeriodStart,
		&i.PeriodEnd,
		&i.State,
		&i.Revision,
		&i.Kwh,
		&i.Estimated,
		&i.IntervalCount,
		&i.ExpectedIntervalCount,
		&i.Blocked,
		&i.BlockedDetail,
		&i.Amount,
		&i.Currency,
		&i.ContractName,
		&i.ComputedAt,
		&i.TouchedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.InvoicedInvoiceID,
		&i.InvoicedNumber,
		&i.InvoicedAt,
		&i.InvoicedByUserID,
		&i.InvoiceDate,
		&i.ReleasedAt,
	)
	return i, err
}

const lockSettlementsByIDs = `-- name: LockSettlementsByIDs :many
SELECT id, supply_period_id, metering_point_id, customer_id, kind, corrects_id, period_start, period_end, state, revision, kwh, estimated, interval_count, expected_interval_count, blocked, blocked_detail, amount, currency, contract_name, computed_at, touched_at, created_at, updated_at, invoiced_invoice_id, invoiced_number, invoiced_at, invoiced_by_user_id, invoice_date, released_at
FROM energy.settlements
WHERE id = ANY($1::bigint[])
ORDER BY id
FOR NO KEY UPDATE
`

// LockSettlementsByIDs is the invoiced-work holder's lock (design D6): the
// settlements by id ascending, FOR NO KEY UPDATE, the order every batch of
// this module keeps.
func (q *Queries) LockSettlementsByIDs(ctx context.Context, ids []int64) ([]EnergySettlement, error) {
	rows, err := q.db.Query(ctx, lockSettlementsByIDs, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []EnergySettlement
	for rows.Next() {
		var i EnergySettlement
		if err := rows.Scan(
			&i.ID,
			&i.SupplyPeriodID,
			&i.MeteringPointID,
			&i.CustomerID,
			&i.Kind,
			&i.CorrectsID,
			&i.PeriodStart,
			&i.PeriodEnd,
			&i.State,
			&i.Revision,
			&i.Kwh,
			&i.Estimated,
			&i.IntervalCount,
			&i.ExpectedIntervalCount,
			&i.Blocked,
			&i.BlockedDetail,
			&i.Amount,
			&i.Currency,
			&i.ContractName,
			&i.ComputedAt,
			&i.TouchedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.InvoicedInvoiceID,
			&i.InvoicedNumber,
			&i.InvoicedAt,
			&i.InvoicedByUserID,
			&i.InvoiceDate,
			&i.ReleasedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const releaseSettlementsInvoiced = `-- name: ReleaseSettlementsInvoiced :many
UPDATE energy.settlements
SET state = 'released',
    released_at = $1::timestamptz,
    updated_at = $1::timestamptz
WHERE id = ANY($2::bigint[]) AND state = 'invoiced' AND invoiced_invoice_id = $3
RETURNING id
`

type ReleaseSettlementsInvoicedParams struct {
	ReleasedAt time.Time
	Ids        []int64
	InvoiceID  *int64
}

// ReleaseSettlementsInvoiced is ReleaseInvoiced's write: the rows carrying the
// invoice's stamp move to released, the stamp kept as history.
func (q *Queries) ReleaseSettlementsInvoiced(ctx context.Context, arg ReleaseSettlementsInvoicedParams) ([]int64, error) {
	rows, err := q.db.Query(ctx, releaseSettlementsInvoiced, arg.ReleasedAt, arg.Ids, arg.InvoiceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int64
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const repointSettlementsCustomer = `-- name: RepointSettlementsCustomer :execrows
UPDATE energy.settlements
SET customer_id = $1::integer
WHERE customer_id = $2::integer
`

type RepointSettlementsCustomerParams struct {
	IntoCustomerID int32
	FromCustomerID int32
}

// RepointSettlementsCustomer is the settlements' half of energy's part of a
// customer merge (plan reading 13): the copied customer id follows the
// supply periods it was copied from.
func (q *Queries) RepointSettlementsCustomer(ctx context.Context, arg RepointSettlementsCustomerParams) (int64, error) {
	result, err := q.db.Exec(ctx, repointSettlementsCustomer, arg.IntoCustomerID, arg.FromCustomerID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const settlementInputsChangedSince = `-- name: SettlementInputsChangedSince :one
SELECT (
    EXISTS (
        SELECT 1 FROM energy.consumption_intervals c
        WHERE c.metering_point_id = $1
          AND c."start" < $2::timestamptz
          AND c."start" >= ($3::timestamptz - interval '1 day')
          AND c."end" > $3::timestamptz
          AND c.received_at > $4::timestamptz
    )
    OR EXISTS (
        SELECT 1 FROM energy.spot_prices p
        WHERE p.price_area = $5
          AND p."start" < $2::timestamptz
          AND p."end" > $3::timestamptz
          AND p.received_at > $4::timestamptz
    )
    OR EXISTS (
        SELECT 1 FROM energy.tariffs t
        WHERE t.id = ANY($6::int[])
          AND t.updated_at > $4::timestamptz
    )
)::bool AS changed
`

type SettlementInputsChangedSinceParams struct {
	MeteringPointID int32
	ToTs            time.Time
	FromTs          time.Time
	Since           time.Time
	PriceArea       string
	TariffIds       []int32
}

// SettlementInputsChangedSince is a correction's trigger (plan reading 8):
// whether an interval of the point in [@from, @to), a price of the area in it,
// or one of the two tariffs was written after @since.
func (q *Queries) SettlementInputsChangedSince(ctx context.Context, arg SettlementInputsChangedSinceParams) (bool, error) {
	row := q.db.QueryRow(ctx, settlementInputsChangedSince,
		arg.MeteringPointID,
		arg.ToTs,
		arg.FromTs,
		arg.Since,
		arg.PriceArea,
		arg.TariffIds,
	)
	var changed bool
	err := row.Scan(&changed)
	return changed, err
}

