const touchSettlements = `-- name: TouchSettlements :exec
UPDATE energy.settlements
SET touched_at = $1::timestamptz
WHERE id = ANY($2::bigint[]) AND state = 'draft' AND touched_at < $1::timestamptz
`

type TouchSettlementsParams struct {
	Now time.Time
	Ids []int64
}

// TouchSettlements records that a read answered the drafts: housekeeping
// deletes only drafts nobody has touched for thirty days (plan reading 7).
func (q *Queries) TouchSettlements(ctx context.Context, arg TouchSettlementsParams) error {
	_, err := q.db.Exec(ctx, touchSettlements, arg.Now, arg.Ids)
	return err
}

